/// <summary>
/// Applies disposition codes.
/// </summary>
class METApplyDispositionCode
{
    SalesTable              salesTable;
    Dialog                  dialogDispostionCode;
    DialogField             dialogFieldDispositionCodeId;
    ReturnDispositionCodeId returnDispositionCodeId;

}

Method.Source:
/// <summary>
/// Gets and sets SalesTable.
/// </summary>
/// <param name = "_salesTable">SalesTable.</param>
/// <returns>SalesTable.</returns>
public SalesTable parmSalesTable(SalesTable _salesTable = salesTable)
{
    salesTable = _salesTable;
    return salesTable;
}

/// <summary>
/// Returns <c>METApplyDispositionCode</c> object.
/// </summary>
/// <returns><c>METApplyDispositionCode</c> object.</returns>
public static METApplyDispositionCode construct()
{
    return new METApplyDispositionCode();
}

/// <summary>
/// Entry point of the class.
/// </summary>
/// <param name = "_args">Args.</param>
public static void main(Args _args)
{
    if (_args.record().TableId != tableNum(SalesTable))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    METApplyDispositionCode applyDispositionCode = METApplyDispositionCode::construct();

    applyDispositionCode.parmSalesTable(_args.record());
    applyDispositionCode.run();
}

/// <summary>
/// Executes the process.
/// </summary>
public void run()
{
    this.init();

    dialogDispostionCode.run();

    if (dialogDispostionCode.closedOk())
    {
        returnDispositionCodeId = dialogFieldDispositionCodeId.value();
        boolean registerLines = (METCustParameters::Find().DispositionCodeRegistration == returnDispositionCodeId);

        if (this.validate())
        {
            SalesLine salesline;

            ttsbegin;

            if (registerLines)
            {
                SalesReturnOrderLineRegister salesReturnOrderLineRegister;
                TradeOrderLineRegister       tradeOrderlineRegister;
                InventTransWMS_Register      inventTransWMS_register;
                TmpInventTransWMS            TmpInventTransWMS;
                InventTransOrigin            inventTransOrigin;
                InventTrans                  inventTrans;

                while select forupdate salesline
                    where salesline.SalesId == SalesTable.SalesId
                    &&    salesline.ReturnDispositionCodeId == ''
                {
                    Args registrationArgs = new Args();
                    tradeOrderLineRegister = SalesReturnOrderLineRegister::construct();

                    registrationArgs.record(salesline);
                    tradeOrderLineRegister.parmArgs(registrationArgs);
                    tradeOrderLineRegister.init();

                    salesReturnOrderLineRegister = tradeOrderLineRegister;
                    salesReturnOrderLineRegister.runPreSuper();

                    //update returnDisposioncode
                    salesline.ReturnDispositionCodeId = returnDispositionCodeId;

                    // Changes done as per Bug404606
                    // Return order header status was not getting changed to open after disposition code been applied
                    // Changes done by Jagjeet Singh on 14/07/2026
                    salesline.modifyField(fieldNum(salesline, ReturnDispositionCodeId));
                    salesline.update();

                   select firstOnly crossCompany inventTrans
                        join RecId, InventTransId from inventTransOrigin
                            where inventTransOrigin.InventTransId == salesline.InventTransId
                                && inventTrans.InventTransOrigin == inventTransOrigin.RecId;

                    inventTransWMS_register = inventTransWMS_register::newStandard(tmpInventTransWMS);

                    tmpInventTransWMS.clear();
                    tmpInventTransWMS.initFromInventTrans(inventTrans);

                    tmpInventTransWMS.InventDimId = inventTrans.InventDimId;
                    tmpInventTransWMS.initFromInventTransOrigin(inventTrans.inventTransOrigin());
                    tmpInventTransWMS.insert();

                    inventTransWMS_register.writeTmpInventTransWMS(tmpInventTransWMS,
                                                                   inventTrans,
                                                                   inventTrans.inventDim());

                    inventTransWMS_register.updateInvent(salesline);
                }
            }
            else
            {
                // Changes done as per Bug404606
                // Return order header status was not getting changed to open after disposition code been applied
                // Changes done by Jagjeet Singh on 14/07/2026                        
                /*
                update_recordset salesline
                    Setting ReturnDispositionCodeId = returnDispositionCodeId
                        where salesline.SalesId == SalesTable.SalesId
                        &&    salesline.ReturnDispositionCodeId == '';

                */

                while select forupdate salesline
                    where salesline.SalesId == SalesTable.SalesId
                        &&    salesline.ReturnDispositionCodeId == ''
                {
                    salesline.ReturnDispositionCodeId = returnDispositionCodeId;
                    salesline.modifyField(fieldNum(salesline, ReturnDispositionCodeId));
                    salesline.update();
                }
            }

            ttscommit;
        }

        if (FormDataUtil::isFormDataSource(salesTable))
        {
            FormDataSource fds = FormDataUtil::getFormDataSource(salesTable);
            fds.research(true);
        }
    }
}

/// <summary>
/// Initializes dialog.
/// </summary>
private void init()
{
    this.initDialog();
}

/// <summary>
/// Initializes dialog.
/// </summary>
private void initDialog()
{
    dialogDispostionCode = new Dialog();

    dialogDispostionCode.caption("@SYS332907");
    dialogDispostionCode.addText("@SYS332908");
    dialogDispostionCode.addText("@SYS332909");

    dialogFieldDispositionCodeId = dialogDispostionCode.addFieldValue(extendedtypestr(ReturnDispositionCodeId), '');
    FormBuildStringControl formStringControlDispositionCodeId = dialogFieldDispositionCodeId.control();
    formStringControlDispositionCodeId.registerOverrideMethod(methodstr(FormStringControl, lookup), methodstr(METApplyDispositionCode, lookupReturnDispositionCode), this);
}

/// <summary>
///     Provides a customized return disposition code drop down list to the dialog.
/// </summary>
/// <param name="_ctrl">
///     A <c>FormStringControl</c> object.
/// </param>
protected void lookupReturnDispositionCode(FormStringControl _ctrl)
{
    ReturnDispositionCode::lookupDispositionCode(_ctrl, '', null);
}

/// <summary>
/// Validates before processing.
/// </summary>
/// <returns>True if valid; otherwise, false.</returns>
private boolean validate()
{
    SalesLine salesLine;
    boolean ret = true;

    select firstonly ReturnDispositionCodeId, RecId from salesLine
        where salesLine.SalesId == salesTable.SalesId
        &&    salesLine.ReturnDispositionCodeId != ''
        &&    salesLine.ReturnDispositionCodeId != returnDispositionCodeId;

    if (salesLine.ReturnDispositionCodeId)
    {
        error(strFmt("@MET:ApplyDispositionCodeError", salesLine.ReturnDispositionCodeId));
        ret = false;
    }

    return ret;
}
